"""Three fixes for the Drilldown horizontal-overflow issue in NB 07:

  1. CSS — let flex children shrink (min-width: 0), chart divs fill container
     (width: 100%), stack vertically on narrow viewports (≤ 900px).
  2. Plotly — add `autosize: true` to all three chart layouts.
  3. Titles — move parent name to an <h3> above the drilldown charts;
     chart titles become shorter so they don't dictate minimum width.
"""
from pathlib import Path
import nbformat
import ast

NB_PATH = Path("/sessions/gifted-great-bell/mnt/task/notebooks/07_Dashboard.ipynb")
nb = nbformat.read(NB_PATH, as_version=4)

# Locate the big HTML-build cell (py[9])
assert nb.cells[9].cell_type == "code"
src = nb.cells[9].source
assert "Plotly.js bundle" in src and "DRILLDOWN_HTML" in src, "py[9] not the HTML build cell"


# ============================================================================
# Patch 1 — CSS: append the responsive rules to the CSS string
# ============================================================================
old_css_tail = 'footer { margin-top: 40px; padding-top: 16px; border-top: 1px solid #ddd; font-size: 12px; color: #666; }\n"""'
new_css_tail = '''footer { margin-top: 40px; padding-top: 16px; border-top: 1px solid #ddd; font-size: 12px; color: #666; }

/* Responsive sizing for Plotly charts and flex layouts */
.macro-row > *, .drilldown-row > * { min-width: 0; }
#quadrant-chart, #parent-bars, #parent-trajectory { width: 100%; }
.parent-name-header { margin: 12px 0 4px 0; font-size: 16px; color: #333; }
@media (max-width: 900px) {
  .macro-row, .drilldown-row { flex-direction: column; }
}
"""'''
assert old_css_tail in src, "CSS tail anchor not found"
src = src.replace(old_css_tail, new_css_tail)


# ============================================================================
# Patch 2 — DRILLDOWN_HTML: add <h3> for parent name above the chart row
# ============================================================================
old_drilldown = '''  <div id="parent-detail" style="display:none;">
    <div class="drilldown-row">
      <div id="parent-bars" style="flex:1;"></div>
      <div id="parent-trajectory" style="flex:1.4;"></div>
    </div>'''
new_drilldown = '''  <div id="parent-detail" style="display:none;">
    <h3 class="parent-name-header" id="parent-name-display"></h3>
    <div class="drilldown-row">
      <div id="parent-bars" style="flex:1;"></div>
      <div id="parent-trajectory" style="flex:1.4;"></div>
    </div>'''
assert old_drilldown in src, "DRILLDOWN_HTML structure not found"
src = src.replace(old_drilldown, new_drilldown)


# ============================================================================
# Patch 3a — Quadrant chart: add autosize to its layout
# ============================================================================
old_quadrant_layout = "height: 580, margin: { t: 30, b: 70, l: 80, r: 140 },"
new_quadrant_layout = "autosize: true, height: 580, margin: { t: 30, b: 70, l: 80, r: 140 },"
assert old_quadrant_layout in src, "Quadrant chart layout anchor not found"
src = src.replace(old_quadrant_layout, new_quadrant_layout)


# ============================================================================
# Patch 3b — Parent-bars chart: shorten title + add autosize
# ============================================================================
old_bars = '''Plotly.newPlot('parent-bars', [{
    type: 'bar', orientation: 'h',
    x: [p.pqs, p.eps, p.scvs],
    y: ['Pledge Quality (PQS)', 'EPA Performance (EPS)', 'Satellite Cross-Val (SCVS)'],
    marker: { color: ['#3949ab', '#ff7043', '#43a047'] },
