"""ROOT-CAUSE fix for the Drilldown horizontal-overflow issue.

Diagnosis: Plotly.newPlot was rendering into the parent-detail div BEFORE that
div was set to display:block. With a display:none container, Plotly cannot
measure the container width — it falls back to a default width (~700px),
which overflows narrow containers. All previous CSS / autosize / title fixes
were addressing downstream symptoms.

Two coordinated changes in onParentChange():
  1. Move `parent-detail.style.display = 'block'` from the END of the function
     to right after the header text update — BEFORE any Plotly.newPlot call.
     This ensures the container has a measurable width when Plotly renders.
  2. After both Plotly.newPlot calls, explicitly call Plotly.Plots.resize() on
     each chart. This forces a re-measure in case the first render happened
     before the browser completed the layout pass triggered by display:block.
"""
from pathlib import Path
import nbformat
import ast

NB_PATH = Path("/sessions/gifted-great-bell/mnt/task/notebooks/07_Dashboard.ipynb")
nb = nbformat.read(NB_PATH, as_version=4)

assert nb.cells[9].cell_type == "code"
src = nb.cells[9].source


# ============================================================================
# Edit 1 — Move display:block BEFORE Plotly.newPlot
# ============================================================================
old_pre_plot = """  document.getElementById('parent-name-display').textContent = '#' + p.rank + '  —  ' + p.name;

  // Three-axis bar chart"""

new_pre_plot = """  document.getElementById('parent-name-display').textContent = '#' + p.rank + '  —  ' + p.name;

  // CRITICAL: show the container BEFORE Plotly.newPlot so the charts can measure
  // their container width. Plotly's autosize requires a visible (non-display:none)
  // parent div; otherwise it falls back to a default width (~700px) that overflows
  // narrow flex containers.
  document.getElementById('parent-detail').style.display = 'block';

  // Three-axis bar chart"""

assert old_pre_plot in src, "Pre-plot anchor not found"
src = src.replace(old_pre_plot, new_pre_plot)


# ============================================================================
# Edit 2 — Remove old display:block at end; add Plotly.Plots.resize calls
# ============================================================================
old_post_text = """  document.getElementById('parent-text').innerHTML =
    '<strong>Cohort rank (by 2023 emissions): #' + p.rank + ' of 50</strong>  •  ' +
    '<strong>Quadrant: ' + p.quadrant + '</strong>  •  ' +
    '<strong>CCCS (current weights):</strong> ' + cccsText + '  •  ' +
    '<strong>CCCS rank:</strong> ' + rankText + '<br>' + badge;
  document.getElementById('parent-detail').style.display = 'block';
}"""

